return [{
  json: {
    jdText: (item['Job Description Text'] || '').trim(),
    roleTitle: item['Role Title (optional, improves accuracy)'] || 'Not specified',
    industry: item['Industry (optional, e.g. Tech, Healthcare, Construction)'] || 'Not specified'
  }
}];

const item = $input.first().json;
let text = item.jdText;
let truncated = false;

if (text.length > 12000) {
  text = text.slice(0, 12000);
  truncated = true;
}

return [{
  json: {
    jdText: text,
    roleTitle: item.roleTitle,
    industry: item.industry,
    truncated
  }
}];

