    "lean": "Masculine-coded",
    "masculine_words_found": [
      "competitive",
      "dominant",
      "rockstar",
      "ninja"
    ],
    "feminine_words_found": [
      "collaborative",
      "supportive"
    ],
    "note": "Masculine-coded words outnumber feminine-coded words roughly 3 to 1 in this text."
  },
  "flags": [
    {
      "phrase": "must be a rockstar ninja developer who thrives in a competitive, high-pressure environment",
      "category": "Gender-Coded",
      "severity": "High",
      "explanation": "Words like 'rockstar', 'ninja', and 'competitive' are masculine-coded and research shows they reduce application rates from women and non-binary candidates.",
      "suggested_rewrite": "must be a skilled developer who thrives in a fast-paced, collaborative environment"
