parameters.jsCode:
const raw = $input.first().json.output;
const data = (raw && typeof raw === 'object') ? raw : null;

if (!data || typeof data.inclusivity_score === 'undefined') {
  const html = `<!DOCTYPE html><html><body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;padding:60px;text-align:center;color:#111827;"><h2>Could not generate a report</h2><p style="color:#6b7280;">The AI response could not be read. Please go back and try again.</p></body></html>`;
  return [{ json: { html } }];
}

const severityColor = (level) => {
  const map = { High: '#dc2626', Medium: '#ea580c', Low: '#ca8a04' };
  return map[level] || '#6b7280';
};

const scoreColor = data.inclusivity_score >= 80 ? '#16a34a' : data.inclusivity_score >= 60 ? '#ca8a04' : '#dc2626';

const wordChips = (words, bg, fg) => (words && words.length)
  ? words.map(w => `<span style="background:${bg};color:${fg};padding:3px 10px;border-radius:999px;font-size:12px;margin-right:6px;display:inline-block;margin-bottom:6px;">${w}</span>`).join('')
  : '<span style="color:#9ca3af;font-size:13px;">None found</span>';

const flagsHtml = (data.flags || []).map(f => `
  <div style="border:1px solid #e5e7eb;border-left:4px solid ${severityColor(f.severity)};border-radius:8px;padding:16px;margin-bottom:14px;background:#fff;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
      <span style="font-weight:600;color:#111827;">${f.category}</span>
      <span style="background:${severityColor(f.severity)};color:#fff;font-size:12px;font-weight:600;padding:3px 10px;border-radius:999px;">${f.severity}</span>
    </div>
    <p style="color:#4b5563;font-style:italic;margin:6px 0;font-size:14px;">"${f.phrase}"</p>
    <p style="color:#111827;margin:6px 0;font-size:14px;"><strong>Why it matters:</strong> ${f.explanation}</p>
    <p style="color:#111827;margin:6px 0;font-size:14px;"><strong>Try instead:</strong> ${f.suggested_rewrite}</p>
  </div>
`).join('');

const noFlagsHtml = `<p style="color:#16a34a;font-weight:600;">No notably discouraging phrases were found in the text provided.</p>`;

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><title>Job Description Bias Report</title></head>
<body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#f9fafb;margin:0;padding:32px;">
  <div style="max-width:680px;margin:0 auto;">
    <h1 style="color:#111827;font-size:22px;margin-bottom:4px;">Job Description Bias Report</h1>
    <p style="color:#6b7280;font-size:13px;margin-top:0;">AI-generated inclusive-language check, based on established gender-coding research and inclusive hiring guidance.</p>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;display:flex;align-items:center;gap:20px;">
      <div style="font-size:36px;font-weight:700;color:${scoreColor};">${data.inclusivity_score}/100</div>
      <div>
        <div style="font-weight:600;color:#111827;">Inclusivity Score</div>
        <div style="color:#4b5563;font-size:14px;">${data.overall_summary}</div>
      </div>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:10px;">Gender Coding: ${data.gender_coding.lean}</div>
      <p style="color:#6b7280;font-size:13px;margin:0 0 10px 0;">${data.gender_coding.note}</p>
      <div style="margin-bottom:8px;"><span style="font-size:13px;color:#111827;font-weight:600;">Masculine-coded: </span>${wordChips(data.gender_coding.masculine_words_found, '#dbeafe', '#1e40af')}</div>
      <div><span style="font-size:13px;color:#111827;font-weight:600;">Feminine-coded: </span>${wordChips(data.gender_coding.feminine_words_found, '#fce7f3', '#9d174d')}</div>
    </div>

    <h2 style="color:#111827;font-size:17px;">Flagged Phrases (${(data.flags||[]).length})</h2>
    ${(data.flags && data.flags.length) ? flagsHtml : noFlagsHtml}

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:6px;">Readability</div>
      <p style="color:#4b5563;font-size:14px;margin:0;">${data.readability_note}</p>
    </div>

    <p style="color:#9ca3af;font-size:12px;margin-top:30px;">Generated by an AI inclusive-language checker. Use it as a starting point alongside your own hiring team's judgment.</p>
  </div>
</body>
</html>`;

return [{ json: { html } }];
